-- ============================================================
--  Spin & Win — load CATEGORY-based gifts from the sheet.
--  Safe to run more than once (uses fixed IDs + ON CONFLICT).
--  Run:  psql "<EXTERNAL_DB_URL>" -f load_categories.sql
-- ============================================================
BEGIN;

-- 1) Hide the old price-based ranges so they don't show as categories.
UPDATE price_slabs SET is_active = false WHERE is_active = true;

-- 2) Categories (stored as global price_slabs; price fields unused).
INSERT INTO price_slabs (id, store_id, name, min_price, max_price, priority, is_active) VALUES
 ('ca700000-0000-0000-0000-000000000001', NULL, 'MOBILE',   0, NULL, 1, true),
 ('ca700000-0000-0000-0000-000000000002', NULL, 'LED',      0, NULL, 2, true),
 ('ca700000-0000-0000-0000-000000000003', NULL, 'LAPTOP',   0, NULL, 3, true),
 ('ca700000-0000-0000-0000-000000000004', NULL, 'REF SD',   0, NULL, 4, true),
 ('ca700000-0000-0000-0000-000000000005', NULL, 'REF DD',   0, NULL, 5, true),
 ('ca700000-0000-0000-0000-000000000006', NULL, 'WM SEMI',  0, NULL, 6, true),
 ('ca700000-0000-0000-0000-000000000007', NULL, 'WM FULLY', 0, NULL, 7, true)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, is_active = true;

-- 3) Gifts (prizes with their value).
INSERT INTO prizes (id, name, value, is_active, priority) VALUES
 ('f1000000-0000-0000-0000-000000000001', 'Ear Buds',         100, true, 1),
 ('f1000000-0000-0000-0000-000000000002', 'Bluetooth Speaker',150, true, 2),
 ('f1000000-0000-0000-0000-000000000003', 'Neck Band',        150, true, 3),
 ('f1000000-0000-0000-0000-000000000004', 'Hand Chopper',     150, true, 4),
 ('f1000000-0000-0000-0000-000000000005', 'Crockery Set',     300, true, 5),
 ('f1000000-0000-0000-0000-000000000006', 'Laptop Bag',       350, true, 6),
 ('f1000000-0000-0000-0000-000000000007', 'Kettle',           350, true, 7),
 ('f1000000-0000-0000-0000-000000000008', 'Iron',             400, true, 8),
 ('f1000000-0000-0000-0000-000000000009', 'Wine Glass Set',   400, true, 9),
 ('f1000000-0000-0000-0000-00000000000a', 'Bed Sheet',        500, true, 10)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, value = EXCLUDED.value, is_active = true;

-- 4) Unlimited stock for each gift (global pool).
INSERT INTO prize_inventory (id, prize_id, store_id, quantity_initial, quantity_remaining, low_stock_threshold)
SELECT ('e1000000-0000-0000-0000-00000000000' || substr(p.id::text, 36, 1))::uuid,
       p.id, NULL, 1000000, 1000000, 0
FROM prizes p
WHERE p.id IN (
  'f1000000-0000-0000-0000-000000000001','f1000000-0000-0000-0000-000000000002',
  'f1000000-0000-0000-0000-000000000003','f1000000-0000-0000-0000-000000000004',
  'f1000000-0000-0000-0000-000000000005','f1000000-0000-0000-0000-000000000006',
  'f1000000-0000-0000-0000-000000000007','f1000000-0000-0000-0000-000000000008',
  'f1000000-0000-0000-0000-000000000009','f1000000-0000-0000-0000-00000000000a')
  AND NOT EXISTS (SELECT 1 FROM prize_inventory i
                  WHERE i.prize_id = p.id AND i.store_id IS NULL);

-- 5) Category -> gift percentages (weight = percentage). Only >0 entries.
